SELECT b.execution_reason, p.status, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS winners, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, ROUND(AVG(p.realized_pnl), 6) AS pnl_avg FROM wallet_trade b JOIN paper_position p ON p.signal_id = b.signal_id WHERE b.side = 'BUY' AND b.status = 'EXECUTED' AND p.closed_at IS NOT NULL GROUP BY b.execution_reason, p.status ORDER BY b.execution_reason, p.status